"""Authored champion constraints and choice-specific advice; no catalog text as advice."""
import csv
import re
from pathlib import Path

PROFILES = {row[0]: row[1:] for row in csv.reader(
    Path(__file__).with_name('champion_coaching_profiles.tsv').read_text().splitlines(), delimiter='|')}
MNEMONICS = {row[0]: row[1:] for row in csv.reader(
    Path(__file__).with_name('champion_coaching_mnemonics.tsv').read_text().splitlines(), delimiter='|')}
assert set(MNEMONICS) == set(PROFILES)

def profile(champion, pt=False):
    risk_es, risk_pt, rule_es, rule_pt = PROFILES[champion['id']]
    return (risk_pt, rule_pt) if pt else (risk_es, rule_es)

def overview(champion, lane, lane_name, translations, pt=False):
    risk, rule = profile(champion, pt)
    # Two independent execution steps, rather than copying an item or a spell.
    steps = rule.split('; ', 1)
    decision = steps[0].rstrip('.')
    detail = steps[-1][0].upper() + steps[-1][1:] if len(steps) == 2 else rule
    name = champion.get('namePt') or champion['name'].replace('Nunu y Willump', 'Nunu e Willump') if pt else champion['name']
    titles = ('Diagnóstico do erro/situação', 'Decisão Soberano', 'Micro e Macro detalhe', 'Regra aplicável') if pt else (
        'Diagnóstico del error/situación', 'Decisión Soberano', 'Micro y Macro detalle', 'Regla aplicable')
    lane_rules = {
        'TOP': ('El intercambio termina antes de perder la ruta a tu torre; prepara la compra con una oleada que alcance la torre rival.', 'A troca termina antes de perder a rota até sua torre; prepare a compra com uma onda que alcance a torre inimiga.'),
        'JUNGLE': ('Elige el campamento de salida por el siguiente objetivo y por la ruta que permite ejecutar esta secuencia, no por perseguir al primer rival.', 'Escolha o campo de saída pelo próximo objetivo e pela rota que permite executar esta sequência, não por perseguir o primeiro inimigo.'),
        'MID': ('Empuja antes de salir solo si puedes conservar la herramienta citada para el río; sin ella, termina la oleada y evita la entrada a ciegas.', 'Avance antes de sair apenas se puder preservar a ferramenta citada para o rio; sem ela, termine a onda e evite a entrada às cegas.'),
        'ADC': ('Mantén la distancia a tu protección durante esta secuencia; compra después de un crash o de un regreso coordinado con tu soporte.', 'Mantenha a distância até sua proteção durante esta sequência; compre depois de uma onda na torre ou de um retorno combinado com seu suporte.'),
        'SUPPORT': ('Tu salida de línea depende de la seguridad del tirador y del recurso citado; vuelve antes de que la oleada lo deje expuesto.', 'Sua saída da rota depende da segurança do atirador e do recurso citado; volte antes de a onda deixá-lo exposto.'),
    }
    return '\n'.join(f'{title}: {body}' for title, body in zip(titles, (
        f'{name} · {lane_name}. {risk}', decision + '.',
        detail + ' ' + lane_rules[lane][int(pt)], MNEMONICS[champion['id']][int(pt)])))

