def element(champion, lane_name, name, kind, pt=False, display_name=None):
    risk, rule = profile(champion, pt)
    if name in ('Destello', 'Flash'):
        return ''
    steps = rule.split('; ', 1)
    anchor = steps[0].rstrip('.')
    continuation = steps[-1] if len(steps) > 1 else rule
    if kind == 'item':
        if name in ITEM_POLICIES:
            values = ITEM_POLICIES[name]
            need, action = values[int(pt)], values[2 + int(pt)]
        elif name in EXTRA_POLICIES:
            action = EXTRA_POLICIES[name][int(pt)]
            need = ('La tarea de esta compra es ' if not pt else 'A tarefa desta compra é ') + action[0].lower() + action[1:]
        elif 'bota' in name.lower() or name in ('Grebas codiciosas', 'Avance blindado', 'Avance mercurial', 'Lucidez carmesí', 'Grebas berserker'):
            need = 'La movilidad debe permitir ejecutar tu condición sin consumir la herramienta de salida.' if not pt else 'A mobilidade deve permitir executar sua condição sem consumir a ferramenta de saída.'
            action = 'Elige la defensa por el daño o control que recibes al acercarte, y conserva tu recurso para volver a cobertura.' if not pt else 'Escolha a defesa pelo dano ou controle ao aproximar e preserve seu recurso para voltar à cobertura.'
        else:
            raise AssertionError(('Item lacks authored policy', name))
    else:
        table = RUNE_POLICIES if kind == 'rune' else SPELL_POLICIES
        action = table[name][int(pt)]
        need = risk
    me = (champion.get('namePt') or champion['name'].replace('Nunu y Willump', 'Nunu e Willump')) if pt else champion['name']
    titles = ('Diagnóstico do erro/situação','Decisão Soberano','Micro e Macro detalhe','Regra aplicável') if pt else ('Diagnóstico del error/situación','Decisión Soberano','Micro y Macro detalle','Regla aplicable')
    return '\n'.join(f'{t}: {v}' for t, v in zip(titles, (
        f'{me} · {lane_name} · {display_name or name}. {need}', action, anchor + '.', continuation[0].upper() + continuation[1:])))
